const floorMat = new THREE.MeshStandardMaterial({
  color: 0xe8ecf1,
  roughness: 0.8,
  metalness: 0.1,
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -6;
floor.receiveShadow = true;
scene.add(floor);

// Wormhole Group
const wormholeGroup = new THREE.Group();
scene.add(wormholeGroup);

// 1. Main funnel (LatheGeometry)
const points = [];
for (let i = 0; i <= 64; i++) {
  const t = i / 64; // 0 to 1
  const z = (t - 0.5) * 12; // -6 to 6
  // Funnel profile: radius large at ends, narrow at center
  // Use a hyperbolic-ish profile: r = 1.5 + 4 * (t*2-1)^2
  const r = 1.2 + 3.8 * Math.pow(Math.abs(t * 2 - 1), 2);
  // Actually LatheGeometry takes Vector2 points (x is radius, y is height/depth along axis)
  // We'll create profile in x-y plane then rotate geometry later
  points.push(new THREE.Vector2(r, z));
}
const funnelGeo = new THREE.LatheGeometry(points, 128);
// Lathe rotates around Y, creating a surface where profile x=radius, y=height.
// We need the tunnel along Z, so rotate geometry -90 deg around X after creation? 
// Actually Lathe spins around Y. The resulting tube axis is Y. Let's keep it Y-aligned 
// and orient the whole group, or just rotate the mesh: rotation.x = -Math.PI/2.
// Let's create the mesh and rotate.
const funnelMat = new THREE.MeshPhysicalMaterial({
  color: 0x1a1a2e,
  metalness: 0.85,
  roughness: 0.25,
  clearcoat: 1.0,
  clearcoatRoughness: 0.1,
  iridescence: 1.0,
  iridescenceIOR: 1.8,
  iridescenceThicknessRange: [100, 400],
  side: THREE.DoubleSide,
});
const funnel = new THREE.Mesh(funnelGeo, funnelMat);
funnel.rotation.x = -Math.PI / 2; // axis now along Z
funnel.castShadow = true;
funnel.receiveShadow = true;
wormholeGroup.add(funnel);

// 2. Inner membrane (slightly smaller, glowing emissive)
const innerPoints = points.map(p => new THREE.Vector2(p.x * 0.85, p.y));
const innerGeo = new THREE.LatheGeometry(innerPoints, 128);
const innerMat = new THREE.MeshPhysicalMaterial({
  color: 0x0a0a1a,
  emissive: 0x223355,
  emissiveIntensity: 0.6,
  metalness: 0.5,
  roughness: 0.4,
  side: THREE.DoubleSide,
});
const innerFunnel = new THREE.Mesh(innerGeo, innerMat);
innerFunnel.rotation.x = -Math.PI / 2;
wormholeGroup.add(innerFunnel);

// 3. Accretion-like rings (Torus) around the funnel
const ringCount = 5;
const rings = [];
for (let i = 0; i < ringCount; i++) {
  const t = (i + 0.5) / ringCount; // position along depth
  const radiusAtT = 1.2 + 3.8 * Math.pow(Math.abs(t * 2 - 1), 2);
  const tube = 0.04 + 0.02 * Math.sin(i * 3);
  const ringGeo = new THREE.TorusGeometry(radiusAtT, tube, 32, 200);
  const hue = i % 2 === 0 ? 0x00ffff : 0xffaa44;
  const ringMat = new THREE.MeshStandardMaterial({
    color: hue,
    emissive: hue,
    emissiveIntensity: 2.5,
    roughness: 0.2,
    metalness: 0.8,
    transparent: true,
    opacity: 0.9,
  });
  const ring = new THREE.Mesh(ringGeo, ringMat);
  ring.position.z = (t - 0.5) * 12;
  ring.rotation.x = Math.PI / 2; // flat ring facing Z
  ring.castShadow = true;
  wormholeGroup.add(ring);
  rings.push({ mesh: ring, baseScale: 1.0, speed: 0.5 + i * 0.2, phase: i * 1.2 });
}

// 4. Spiral particle streams (flowing into throat)
const streamCount = 4;
const streamParticles = [];
const streamParticleCount = 800;
for (let s = 0; s < streamCount; s++) {
  const geo = new THREE.BufferGeometry();
  const positions = new Float32Array(streamParticleCount * 3);
  const randoms = new Float32Array(streamParticleCount); // for offset
  for (let i = 0; i < streamParticleCount; i++) {
    // initialize along spiral
    const prog = Math.random(); // 0..1 position along Z depth
    const angle = prog * Math.PI * 8 + (s * (Math.PI * 2 / streamCount));
    const r = 1.2 + 3.8 * Math.pow(Math.abs(prog * 2 - 1), 2) + 0.3; // slightly outside funnel
    const z = (prog - 0.5) * 12;
    positions[i * 3] = Math.cos(angle) * r;
    positions[i * 3 + 1] = Math.sin(angle) * r;
    positions[i * 3 + 2] = z;
    randoms[i] = Math.random();
  }
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('aRandom', new THREE.BufferAttribute(randoms, 1));
  const mat = new THREE.PointsMaterial({
    color: s % 2 === 0 ? 0x44aaff : 0xffaa66,
    size: 0.08,
    transparent: true,
    opacity: 0.7,
    sizeAttenuation: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const pts = new THREE.Points(geo, mat);
  wormholeGroup.add(pts);
  streamParticles.push({ points: pts, count: streamParticleCount, offset: s });
}

// 5. Ambient dust particles
const dustCount = 1200;
const dustGeo = new THREE.BufferGeometry();
const dustPos = new Float32Array(dustCount * 3);
for (let i = 0; i < dustCount; i++) {
  dustPos[i * 3] = (Math.random() - 0.5) * 30;
  dustPos[i * 3 + 1] = (Math.random() - 0.5) * 20;
  dustPos[i * 3 + 2] = (Math.random() - 0.5) * 30;
}
dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3));
const dustMat = new THREE.PointsMaterial({
  color: 0x88aacc,
  size: 0.05,
  transparent: true,
  opacity: 0.35,
  sizeAttenuation: true,
});
const dust = new THREE.Points(dustGeo, dustMat);
scene.add(dust);

