// Animation loop
function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Rotate entire wormhole slowly
  wormholeGroup.rotation.z = t * 0.05;
  wormholeGroup.rotation.y = t * 0.03;

  // Pulse rings and spin them
  rings.forEach((ring, idx) => {
    const r = ring.mesh;
    // spin
    r.rotation.z = t * ring.speed;
